const body = $input.first().json.body || {};
const headers = $input.first().json.headers || {};
const text = body.message || '';

// Webhook signature validation
const providedSignature = headers['x-teams-signature'];
const expectedSignature = $vars.WEBHOOK_SECRET || process.env.WEBHOOK_SECRET;

if (!expectedSignature) {
  throw new Error('❌ SECURITY_ERROR: WEBHOOK_SECRET not configured');
}

if (providedSignature !== expectedSignature) {
  throw new Error('❌ SECURITY_ERROR: Invalid webhook signature');
}

// Strict validation
if (!text || text.trim().length < 10) {
  throw new Error('❌ VALIDATION_ERROR: Message too short (min 10 chars)');
}

if (text.length > 5000) {
  throw new Error('❌ VALIDATION_ERROR: Message too long (max 5000 chars)');
}

// Aggressive sanitization - strip ALL HTML/script content
const sanitized = text
  .replace(/<[^>]*>/g, '')
  .trim();

// Load from environment variables with strict validation
const JIRA_PROJECT = $vars.JIRA_PROJECT_KEY || process.env.JIRA_PROJECT_KEY;
const JIRA_DOMAIN = $vars.JIRA_DOMAIN || process.env.JIRA_DOMAIN;
const PAGERDUTY_SERVICE = $vars.PAGERDUTY_SERVICE_ID || process.env.PAGERDUTY_SERVICE_ID;
const PAGERDUTY_EMAIL = $vars.PAGERDUTY_EMAIL || process.env.PAGERDUTY_EMAIL;
const TIMEZONE = $vars.TIMEZONE || process.env.TIMEZONE || 'UTC';

// Validate critical config - fail hard on missing values
if (!JIRA_PROJECT) {
  throw new Error('❌ CONFIG_ERROR: JIRA_PROJECT_KEY not configured');
}

if (!JIRA_DOMAIN || JIRA_DOMAIN.includes('your-domain')) {
  throw new Error('❌ CONFIG_ERROR: JIRA_DOMAIN not configured or using placeholder');
}

if (!PAGERDUTY_SERVICE || PAGERDUTY_SERVICE === 'PXXXXXX') {
  throw new Error('❌ CONFIG_ERROR: PAGERDUTY_SERVICE_ID not configured or using placeholder');
}

if (!PAGERDUTY_EMAIL || !PAGERDUTY_EMAIL.includes('@') || PAGERDUTY_EMAIL.includes('company.com')) {
  throw new Error('❌ CONFIG_ERROR: PAGERDUTY_EMAIL not configured or using placeholder');
}

// Validate timezone format
const validTimezone = TIMEZONE.includes('/') || TIMEZONE === 'UTC';
if (!validTimezone) {
  console.warn(`⚠️ WARNING: Invalid timezone format '${TIMEZONE}', using UTC`);
}

const incident_id = body.incident_id || `INC-${Date.now()}`;

return {
  json: {
    sanitized_text: sanitized,
    JIRA_PROJECT_KEY: JIRA_PROJECT,
    JIRA_DOMAIN: JIRA_DOMAIN,
    PAGERDUTY_SERVICE_ID: PAGERDUTY_SERVICE,
    PAGERDUTY_EMAIL: PAGERDUTY_EMAIL,
    TIMEZONE: validTimezone ? TIMEZONE : 'UTC',
    channelId: body.channelId || 'general',
    reporterName: body.userName || 'Engineer',
    reporterEmail: body.userEmail || 'user@example.com',
    timestamp: new Date().toISOString(),
    incident_id: incident_id,
    validation_passed: true
  }
};

// Check for duplicate incidents (idempotency)
const incident_id = $input.first().json.incident_id;
const REDIS_KEY = `incident:processed:${incident_id}`;

const recentIncidents = $getWorkflowStaticData('global').recentIncidents || [];

if (recentIncidents.includes(incident_id)) {
  throw new Error(`❌ DUPLICATE: Incident ${incident_id} already processed`);
}


recentIncidents.push(incident_id);
if (recentIncidents.length > 1000) {
  recentIncidents.shift();
}
$getWorkflowStaticData('global').recentIncidents = recentIncidents;

return $input.all();

try {
  const aiOutput = $input.first().json;
  const aiContent = aiOutput.choices?.[0]?.message?.content || aiOutput.message?.content || aiOutput.content || '';

  const jsonMatch = aiContent.match(/\{[\s\S]*\}/);
  if (!jsonMatch) {
    throw new Error('No JSON object found in AI response');
  }

  const cleanJson = jsonMatch[0];
  const triage = JSON.parse(cleanJson);
  const config = $('Extract & Validate').first().json;


  const required = {
    'title': 'string',
    'severity': 'string',
    'requires_pagerduty': 'boolean',
    'cause_hypothesis': 'string',
    'affected_systems': 'array',
    'actions': 'array',
    'business_impact': 'string',
    'estimated_users_affected': 'string',
    'affected_service': 'string',
    'customer_facing': 'boolean'
  };

  for (const [field, type] of Object.entries(required)) {
    if (triage[field] === undefined) {
      throw new Error(`Missing required field: ${field}`);
    }
    const actualType = Array.isArray(triage[field]) ? 'array' : typeof triage[field];
    if (actualType !== type) {
      throw new Error(`Field ${field} should be ${type}, got ${actualType}`);
    }
  }

  const validSeverities = ['P1', 'P2', 'P3', 'P4'];
  if (!validSeverities.includes(triage.severity)) {
    console.warn(`⚠️ Invalid severity ${triage.severity}, defaulting to P3`);
    triage.severity = 'P3';
  }

  const priorityMap = {
    'P1': 'Highest',
    'P2': 'High',
    'P3': 'Medium',
    'P4': 'Low'
  };


  return {
    json: {
      title: triage.title,
      severity: triage.severity,
      requires_pagerduty: triage.requires_pagerduty,
      cause_hypothesis: triage.cause_hypothesis,
      affected_systems: triage.affected_systems,
      actions: triage.actions,
      business_impact: triage.business_impact,
      estimated_users_affected: triage.estimated_users_affected,
      affected_service: triage.affected_service,
      customer_facing: triage.customer_facing,
      jira_priority: priorityMap[triage.severity],
      JIRA_PROJECT_KEY: config.JIRA_PROJECT_KEY,
      JIRA_DOMAIN: config.JIRA_DOMAIN,
      PAGERDUTY_SERVICE_ID: config.PAGERDUTY_SERVICE_ID,
      PAGERDUTY_EMAIL: config.PAGERDUTY_EMAIL,
      TIMEZONE: config.TIMEZONE,
      channelId: config.channelId,
      reporterName: config.reporterName,
      reporterEmail: config.reporterEmail,
      timestamp: config.timestamp,
      incident_id: config.incident_id,
      parse_success: true,
      parse_method: 'ai'
    }
  };
} catch (e) {

  const config = $('Extract & Validate').first().json;

  return {
    json: {
      title: "AI Parse Failed - Manual Triage Required",
      severity: "P3",
      requires_pagerduty: false,
      cause_hypothesis: `AI parsing error: ${e.message}`,
      affected_systems: ["Unknown - Requires Manual Review"],
      actions: [
        "Review original message in Teams",
        "Check AI response format",
        "Manually classify severity"
      ],
      business_impact: "Unable to auto-triage, requires human review",
      estimated_users_affected: "Unknown",
      affected_service: "Unknown",
      customer_facing: false,
      jira_priority: 'Medium',
      JIRA_PROJECT_KEY: config.JIRA_PROJECT_KEY,
      JIRA_DOMAIN: config.JIRA_DOMAIN,
      PAGERDUTY_SERVICE_ID: config.PAGERDUTY_SERVICE_ID,
      PAGERDUTY_EMAIL: config.PAGERDUTY_EMAIL,
      TIMEZONE: config.TIMEZONE,
      channelId: config.channelId,
      reporterName: config.reporterName,
      reporterEmail: config.reporterEmail,
      timestamp: config.timestamp,
      incident_id: config.incident_id,
      parse_success: false,
      parse_method: 'fallback',
      parse_error: e.message
    }
  };
}

const triage = $('Parse & Enrich').first().json;
const jira = $input.first().json;
const jiraUrl = `${triage.JIRA_DOMAIN}/browse/${jira.key || 'ERROR'}`;

const escape = (str) => {
  if (typeof str !== 'string') return String(str);
  return str.replace(/[{}[\]"\\]/g, '\\$&').replace(/\n/g, '\\n');
};

const severityConfig = {
  'P1': { emoji: '🔴', color: 'attention', label: 'CRITICAL' },
  'P2': { emoji: '🟠', color: 'warning', label: 'HIGH' },
  'P3': { emoji: '🟡', color: 'good', label: 'MEDIUM' },
  'P4': { emoji: '🟢', color: 'default', label: 'LOW' }
};

const config = severityConfig[triage.severity] || severityConfig['P3'];

let formattedTime;
try {
  formattedTime = new Date(triage.timestamp).toLocaleString('en-US', {
    timeZone: triage.TIMEZONE,
    dateStyle: 'short',
    timeStyle: 'short',
    hour12: false
  });
} catch (e) {
  console.warn(`⚠️ Timezone error: ${e.message}, using ISO format`);
  formattedTime = new Date(triage.timestamp).toISOString();
}

const card = {
  type: 'AdaptiveCard',
  version: '1.6',
  body: [
    {
      type: 'Container',
      style: config.color,
      items: [
        {
          type: 'TextBlock',
          text: `${config.emoji} ${config.label}: ${escape(triage.title)}`,
          weight: 'Bolder',
          size: 'Large',
          wrap: true,
          color: triage.severity === 'P1' ? 'attention' : 'default'
        }
      ]
    },
    {
      type: 'ColumnSet',
      separator: true,
      spacing: 'Small',
      columns: [
        {
          type: 'Column',
          width: 'auto',
          items: [
            {
              type: 'TextBlock',
              text: `👤 ${escape(triage.reporterName)}`,
              size: 'Small',
              wrap: true
            }
          ]
        },
        {
          type: 'Column',
          width: 'stretch',
          items: [
            {
              type: 'TextBlock',
              text: `🕐 ${formattedTime}`,
              size: 'Small',
              horizontalAlignment: 'Right'
            }
          ]
        }
      ]
    },
    {
      type: 'FactSet',
      separator: true,
      facts: [
        { title: '🎫 Ticket', value: escape(jira.key || 'Creation failed') },
        { title: '📊 Severity', value: `${triage.severity} (${triage.jira_priority})` },
        { title: '🔧 Service', value: escape(triage.affected_service) },
        { title: '👥 Users', value: escape(triage.estimated_users_affected) },
        { title: '🌐 Customer', value: triage.customer_facing ? 'Yes' : 'No' }
      ]
    },
    {
      type: 'TextBlock',
      text: '**💥 Business Impact**',
      weight: 'Bolder',
      size: 'Small',
      separator: true
    },
    {
      type: 'TextBlock',
      text: escape(triage.business_impact),
      wrap: true,
      size: 'Small',
      color: triage.customer_facing ? 'attention' : 'default'
    },
    {
      type: 'TextBlock',
      text: '**🔍 Systems Affected**',
      weight: 'Bolder',
      size: 'Small',
      separator: true
    },
    {
      type: 'TextBlock',
      text: triage.affected_systems.map(s => `• ${escape(s)}`).join('\\n'),
      wrap: true,
      size: 'Small'
    },
    {
      type: 'TextBlock',
      text: '**💡 Hypothesis**',
      weight: 'Bolder',
      size: 'Small',
      separator: true
    },
    {
      type: 'TextBlock',
      text: escape(triage.cause_hypothesis),
      wrap: true,
      size: 'Small'
    },
    {
      type: 'TextBlock',
      text: '**✅ Recommended Actions**',
      weight: 'Bolder',
      size: 'Small',
      separator: true
    },
    {
      type: 'TextBlock',
      text: triage.actions.map((a, i) => `${i + 1}. ${escape(a)}`).join('\\n'),
      wrap: true,
      size: 'Small'
    }
  ],
  actions: [
    {
      type: 'Action.OpenUrl',
      title: '📋 View Jira Ticket',
      url: jiraUrl,
      style: 'positive'
    }
  ]
};

// Add PagerDuty indicator if triggered
if (triage.requires_pagerduty) {
  card.body.splice(1, 0, {
    type: 'TextBlock',
    text: '🚨 **PagerDuty Alert Triggered**',
    size: 'Small',
    color: 'attention',
    weight: 'Bolder'
  });
}

// Add AI parse warning if fallback
if (!triage.parse_success) {
  card.body.push({
    type: 'Container',
    separator: true,
    style: 'warning',
    items: [
      {
        type: 'TextBlock',
        text: '⚠️ AI parsing failed. This ticket requires manual review.',
        size: 'Small',
        weight: 'Bolder',
        wrap: true
      }
    ]
  });
}

return {
  json: {
    title: triage.title,
    severity: triage.severity,
    requires_pagerduty: triage.requires_pagerduty,
    jira_key: jira.key,
    jira_url: jiraUrl,
    adaptive_card: card,
    formatted_timestamp: formattedTime,
    incident_id: triage.incident_id,
    reporterName: triage.reporterName,
    affected_service: triage.affected_service,
    customer_facing: triage.customer_facing,
    parse_success: triage.parse_success,
    parse_method: triage.parse_method,
    timestamp: triage.timestamp,
    PAGERDUTY_SERVICE_ID: triage.PAGERDUTY_SERVICE_ID,
    PAGERDUTY_EMAIL: triage.PAGERDUTY_EMAIL
  }
};

const success = $input.first().json;

const logEntry = {
  workflow: 'incident-triage',
  version: '2.1',
  status: 'success',
  incident_id: success.incident_id,
  jira_key: success.jira_key,
  jira_url: success.jira_url,
  severity: success.severity,
  pagerduty_triggered: success.requires_pagerduty,
  ai_parse_success: success.parse_success,
  parse_method: success.parse_method,
  reporter: success.reporterName,
  affected_service: success.affected_service,
  customer_facing: success.customer_facing,
  timestamp: new Date().toISOString(),
  execution_time_ms: Date.now() - new Date(success.timestamp).getTime()
};

console.log('✅ INCIDENT_TRIAGE_SUCCESS:', JSON.stringify(logEntry));


return { json: logEntry };
